class Solution {
    public ListNode sortList(ListNode head) {
        ListNode dummy = new ListNode(Integer.MIN_VALUE);
        while (head != null) {
            ListNode next = head.next, at = dummy;
            while (at.next != null && at.next.val < head.val) at = at.next;
            head.next = at.next;
            at.next = head;
            head = next;
        }
        return dummy.next;
    }
}

