class Solution {
    public int longestSubstring(String s, int k) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; i++) {
            int[] count = new int[26];
            for (int j = i; j < n; j++) {
                count[s.charAt(j) - 'a']++;
                boolean ok = true;
                for (int c : count) if (c > 0 && c < k) { ok = false; break; }
                if (ok) best = Math.max(best, j - i + 1);
            }
        }
        return best;
    }
}

