class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        best = 0
        for u in range(1, 27):
            count = [0] * 26
            distinct = at_least_k = left = 0
            for right, ch in enumerate(s):
                c = ord(ch) - 97
                if count[c] == 0:
                    distinct += 1
                count[c] += 1
                if count[c] == k:
                    at_least_k += 1
                while distinct > u:
                    d = ord(s[left]) - 97
                    left += 1
                    if count[d] == k:
                        at_least_k -= 1
                    count[d] -= 1
                    if count[d] == 0:
                        distinct -= 1
                if distinct == u and at_least_k == u:
                    best = max(best, right - left + 1)
        return best

